const x0 = 2.6 * Math.sin(t * 0.6);
const slope = df(x0);
const y0 = f(x0);
// tangent segment on f
const dx = 1.3;
v.line(x0 - dx, y0 - slope * dx, x0 + dx, y0 + slope * dx, { color: H.colors.good, width: 2.5 });
